form.script:
var MAX_DELIVERY_STOPS = 20;
var stopCounter = 1; // starts at 1, Stop 1 already rendered

// Template for a new stop row (cloned from Stop 1 style)
function createStopRow(index) {
    var tmpl = document.querySelector('.delivery-stop-row');
    if (!tmpl) return null;
    var row = tmpl.cloneNode(true);
    row.setAttribute('data-stop-index', index);
    row.querySelector('.stop-label').textContent = 'Delivery Stop ' + (index + 1);
    // Update select name
    var sel = row.querySelector('select');
    sel.name = 'delivery_saved_location_id_' + (index + 1);
    sel.value = '';
    sel.classList.remove('is-valid');
    // Clear detail text
    row.querySelector('.stop-detail-text').textContent = '';
    // Update add-loc link
    var addLoc = row.querySelector('.add-loc-link');
    if (addLoc) addLoc.href = '/my/saved-locations/add?type=delivery&return=booking&stop_index=' + (index + 1);
    // Show all buttons (hidden on template)
    row.querySelector('.move-up-btn').style.display = '';
    row.querySelector('.move-down-btn').style.display = '';
    row.querySelector('.remove-stop-btn').style.display = '';
    return row;
}

function rebindStopRow(row, index, total) {
    // Label
    row.querySelector('.stop-label').textContent = 'Delivery Stop ' + (index + 1);
    // Select name
    var sel = row.querySelector('select');
    sel.name = 'delivery_saved_location_id_' + (index + 1);
    // Add-loc link
    var addLoc = row.querySelector('.add-loc-link');
    if (addLoc) addLoc.href = '/my/saved-locations/add?type=delivery&return=booking&stop_index=' + (index + 1);
    // Move up: hide for first
    row.querySelector('.move-up-btn').style.display = (index > 0) ? '' : 'none';
    // Move down: hide for last
    row.querySelector('.move-down-btn').style.display = (index < total - 1) ? '' : 'none';
    // Remove: show for all but stop 0 when total > 1
    row.querySelector('.remove-stop-btn').style.display = (total > 1) ? '' : 'none';
    // Bind select change
    bindSelectDetail(row);
}

function bindSelectDetail(row) {
    var sel = row.querySelector('select');
    var detail = row.querySelector('.stop-detail-text');
    if (!sel || !detail) return;
    sel.addEventListener('change', function() {
        var opt = sel.options[sel.selectedIndex];
        if (opt && opt.value) {
            var street = opt.getAttribute('data-street') || '';
            var city = opt.getAttribute('data-city') || '';
            detail.innerHTML = 'Selected: <strong>' + opt.text.replace(/ ★ \(Default\)/, '') + '</strong>' +
                (street ? ' — ' + street + (city ? ', ' + city : '') : '');
        } else {
            detail.textContent = '';
        }
    });
}

function refreshAllStops() {
    var rows = document.querySelectorAll('.delivery-stop-row');
    var total = rows.length;
    stopCounter = total;
    rows.forEach(function(row, i) {
        row.setAttribute('data-stop-index', i);
        rebindStopRow(row, i, total);
    });
    document.getElementById('max_stops_msg').style.display = (total >= MAX_DELIVERY_STOPS) ? '' : 'none';
    document.getElementById('add_delivery_stop_btn').style.display = (total >= MAX_DELIVERY_STOPS) ? 'none' : '';
}

document.getElementById('add_delivery_stop_btn').addEventListener('click', function(e) {
    e.preventDefault();
    var rows = document.querySelectorAll('.delivery-stop-row');
    if (rows.length >= MAX_DELIVERY_STOPS) return;
    var newRow = createStopRow(rows.length);
    if (newRow) {
        document.getElementById('delivery_stops_container').insertBefore(
            newRow, document.getElementById('max_stops_msg')
        );
        refreshAllStops();
    }
});

// Delegate clicks for move/remove buttons
document.getElementById('delivery_stops_container').addEventListener('click', function(e) {
    var btn = e.target.closest('button');
    if (!btn) return;
    var row = btn.closest('.delivery-stop-row');
    if (!row) return;

    if (btn.classList.contains('move-up-btn')) {
        var prev = row.previousElementSibling;
        if (prev && prev.classList.contains('delivery-stop-row')) {
            row.parentNode.insertBefore(row, prev);
            refreshAllStops();
        }
    } else if (btn.classList.contains('move-down-btn')) {
        var next = row.nextElementSibling;
        if (next && next.classList.contains('delivery-stop-row')) {
            row.parentNode.insertBefore(next, row);
            refreshAllStops();
        }
    } else if (btn.classList.contains('remove-stop-btn')) {
        var rows = document.querySelectorAll('.delivery-stop-row');
        if (rows.length <= 1) return;
        row.remove();
        refreshAllStops();
    }
});

// Initialize Stop 1
document.addEventListener('DOMContentLoaded', function() {
    bindSelectDetail(document.querySelector('.delivery-stop-row'));
    refreshAllStops();
    // Bind pickup detail
    var puSel = document.querySelector('select[name="pickup_saved_location_id"]');
    var puDetail = document.getElementById('pickup_detail_text');
    if (puSel && puDetail) {
        function refreshPu() {
            var opt = puSel.options[puSel.selectedIndex];
            if (opt && opt.value) {
                puDetail.innerHTML = 'Selected: <strong>' + opt.text.replace(/ ★ \(Default\)/, '') + '</strong>';
            } else {
                puDetail.innerHTML = '';
            }
        }
        puSel.addEventListener('change', refreshPu);
        refreshPu();
    }
});

div.script:
document.addEventListener('DOMContentLoaded', function() {
    // Auto-select the only real option in each dropdown
    // when nothing is pre-selected (no default flag set)
    ['pickup_saved_location_id', 'delivery_saved_location_id'].forEach(function(name) {
        var sel = document.querySelector('select[name="' + name + '"]');
        if (!sel) return;
        // Count real options (value != "")
        var realOpts = Array.from(sel.options).filter(function(o) { return o.value !== ''; });
        if (realOpts.length === 1 && sel.value === '') {
            sel.value = realOpts[0].value;
        }
    });
});

t.script:
document.addEventListener('DOMContentLoaded', function() {
    var newId = '';
    var newType = '';
    if (newType === 'pickup' || newType === 'both') {
        var pu = document.querySelector('select[name="pickup_saved_location_id"]');
        if (pu) { pu.value = newId; }
    }
    if (newType === 'delivery' || newType === 'both') {
        var de = document.querySelector('select[name="delivery_saved_location_id"]');
        if (de) { de.value = newId; }
    }
});

form.script:
function togglePortalTemperature() {
    var select = document.getElementById('portal_temperature_mode');
    var row = document.getElementById('portal_required_temperature');
    var input = document.getElementById('portal_required_temperature_input');
    var reefer = select && select.value === 'reefer';
    if (row) { row.style.display = reefer ? '' : 'none'; }
    if (input) {
        input.required = reefer;
        // Set default 15°C when Reefer is selected and value is empty
        if (reefer && !input.value) { input.value = '15'; }
    }
}

template.script:
document.addEventListener('DOMContentLoaded', function() {
    // ════════════════════════════════════════════════════════════
    // Weight auto-calc: pallets × 500 lb, manual override
    // ════════════════════════════════════════════════════════════
    var palletsEl = document.getElementById('pallets_input');
    var weightEl = document.getElementById('weight_input');
    var weightHint = document.getElementById('weight_hint');
    var resetLink = document.getElementById('reset_weight_link');
    var weightManual = false;
    var WEIGHT_PER_PALLET = 500;  // initial fallback; updated from the corridor config via the capacity endpoint

    function autoWeight() {
        if (weightManual) return;
        var p = parseInt(palletsEl.value) || 1;
        weightEl.value = p * WEIGHT_PER_PALLET;
        weightHint.style.display = 'none';
    }
    // Exposed for the stepper and capacity-refresh paths so the
    // weight always tracks pallet changes (programmatic writes do
    // not fire 'input' events).
    function syncCalculatedWeight() { autoWeight(); }
    if (palletsEl && weightEl) { syncCalculatedWeight(); }  // initial load
    if (palletsEl && weightEl) {
        palletsEl.addEventListener('input', function() { autoWeight(); fetchEligibleDates(); });
        weightEl.addEventListener('input', function() { if (document.activeElement === weightEl) { weightManual = true; weightHint.style.display = ''; } });
        weightEl.addEventListener('focus', function() { weightManual = true; weightHint.style.display = ''; });
        if (resetLink) { resetLink.addEventListener('click', function(e) { e.preventDefault(); weightManual = false; autoWeight(); }); }
    }

    // ════════════════════════════════════════════════════════════
    // Date helpers
    // ════════════════════════════════════════════════════════════
    var DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    var DAYS_SHORT = ['SUN','MON','TUE','WED','THU','FRI','SAT'];
    var MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    var MONTHS_SHORT = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

    function fmtDisplay(ds) {
        var d = new Date(ds + 'T00:00:00');
        return DAYS[d.getDay()] + ', ' + MONTHS[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
    }
    function fmtCardDate(ds) {
        var d = new Date(ds + 'T00:00:00');
        return {day: DAYS_SHORT[d.getDay()], date: MONTHS_SHORT[d.getMonth()].toUpperCase() + ' ' + d.getDate()};
    }
    function ymd(d) {
        return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
    }

    // ════════════════════════════════════════════════════════════
    // State
    // ════════════════════════════════════════════════════════════
    var hiddenDate = document.getElementById('requested_pickup_date');
    var displayEl = document.getElementById('selected_date_display');
    var cardsDiv = document.getElementById('pickup_date_cards');
    var viewMore = document.getElementById('view_more_dates');
    var calExpanded = document.getElementById('pickup_calendar_expanded');
    var calBody = document.getElementById('pickup_calendar_body');
    var legendDiv = document.getElementById('pickup_calendar_legend');
    var allDates = [];      // full eligible dates from backend
    var dateMap = {};       // date_str → metadata
    var calendarMonth = null; // {year, month} for the expanded calendar

    // ════════════════════════════════════════════════════════════
    // Select a date — single source of truth
    // ════════════════════════════════════════════════════════════
    function selectDate(ds) {
        if (!ds || !dateMap[ds]) return;
        hiddenDate.value = ds;
        displayEl.textContent = fmtDisplay(ds);
        renderCards();
        if (calExpanded.style.display !== 'none') renderCalendarGrid();
        refreshPalletCapacity();
    }

    // ════════════════════════════════════════════════════════════
    // Dynamic pallet capacity (canonical VehicleCapacityService)
    // ════════════════════════════════════════════════════════════
    var palletsMax = 0;        // dynamic remaining capacity for the selected departure
    var palletsInput = document.getElementById('pallets_input');
    var capacityHint = document.getElementById('pallets_capacity_hint');
    var capacityError = document.getElementById('pallets_capacity_error');
    var getPriceBtn = document.querySelector('button[type="submit"]');

    function showCapacityError(msg) {
        capacityError.textContent = msg;
        capacityError.style.display = msg ? '' : 'none';
    }

    function applyPalletMax() {
        if (palletsMax >= 1) {
            palletsInput.max = palletsMax;
            palletsInput.min = 1;
            var cur = parseInt(palletsInput.value || '1', 10);
            if (isNaN(cur) || cur < 1) { palletsInput.value = 1; }
            else if (cur > palletsMax) { palletsInput.value = palletsMax; }
            capacityHint.textContent = palletsMax + ' pallet position' + (palletsMax === 1 ? '' : 's') + ' available on this departure';
            palletsInput.disabled = false;
            if (getPriceBtn) { getPriceBtn.disabled = false; }
            showCapacityError('');
            syncCalculatedWeight();
            if (typeof buildPalletAllocations === 'function') { buildPalletAllocations(); }
        } else {
            palletsInput.max = 1;
            palletsInput.value = '';
            palletsInput.disabled = true;
            capacityHint.textContent = 'This departure is fully booked. Please choose another pickup date.';
            if (getPriceBtn) { getPriceBtn.disabled = true; }
            showCapacityError('');
        }
    }

    function refreshPalletCapacity() {
        var date = hiddenDate.value;
        var puLat = parseFloat(document.querySelector('input[name="pickup_lat"]')?.value || 0);
        var puLng = parseFloat(document.querySelector('input[name="pickup_lng"]')?.value || 0);
        if (!date) return;
        capacityHint.textContent = 'Checking capacity…';
        var params = 'pickup_date=' + encodeURIComponent(date) +
            '&pickup_lat=' + puLat + '&pickup_lng=' + puLng;
        fetch('/my/booking/capacity?' + params, {credentials: 'same-origin'})
            .then(function(r) { return r.json(); })
            .then(function(data) {
                if (data && data.available) {
                    palletsMax = data.remaining_pallets;
                } else if (data && !data.available) {
                    palletsMax = 0;   // no service on this date
                } else {
                    palletsMax = 0;
                }
                if (data && data.per_pallet_weight) {
                    WEIGHT_PER_PALLET = data.per_pallet_weight;
                    if (resetLink) { resetLink.textContent = 'Reset to ' + WEIGHT_PER_PALLET + ' lb/pallet'; }
                }
                applyPalletMax();
                syncCalculatedWeight();
            })
            .catch(function() {
                palletsMax = 0;
                capacityHint.textContent = 'Could not check capacity. Please try again.';
            });
    }

    function stepPallets(delta) {
        if (palletsInput.disabled) return;
        var cur = parseInt(palletsInput.value || '1', 10);
        if (isNaN(cur)) { cur = 1; }
        var next = cur + delta;
        if (delta > 0 && cur >= palletsMax) {
            showCapacityError('You have reached the maximum available capacity for this departure.');
            return;
        }
        if (next < 1) { next = 1; }
        if (next > palletsMax) { next = palletsMax; }
        palletsInput.value = next;
        showCapacityError('');
        syncCalculatedWeight();
        if (typeof buildPalletAllocations === 'function') { buildPalletAllocations(); }
    }

    function validatePalletInput() {
        if (palletsInput.disabled) return true;
        var raw = palletsInput.value;
        var cur = parseInt(raw, 10);
        if (raw === '' || isNaN(cur) || cur < 1) {
            showCapacityError('Please enter a valid pallet quantity (1 or more).');
            return false;
        }
        if (cur > palletsMax) {
            showCapacityError('Only ' + palletsMax + ' pallet positions are available on this departure.');
            return false;
        }
        showCapacityError('');
        return true;
    }
    if (palletsInput) {
        palletsInput.addEventListener('blur', validatePalletInput);
        palletsInput.addEventListener('input', function() {
            var cur = parseInt(palletsInput.value, 10);
            if (!isNaN(cur) && palletsMax >= 1 && cur > palletsMax) {
                showCapacityError('Only ' + palletsMax + ' pallet positions are available on this departure.');
            } else {
                showCapacityError('');
            }
        });
        palletsInput.addEventListener('wheel', function(ev) {
            // Browser spinner cannot exceed the dynamic max.
            if (palletCapacityAtMax()) { ev.preventDefault(); }
        });
    }
    function palletCapacityAtMax() {
        return parseInt(palletsInput.value || '0', 10) >= palletsMax;
    }
    if (palletsInput) {
        var palletForm = palletsInput.closest('form');
        if (palletForm) {
            palletForm.addEventListener('submit', function(ev) {
                if (!validatePalletInput()) { ev.preventDefault(); }
            });
        }
    }
    // Stepper buttons: bound listeners instead of inline onclick, so
    // the control never depends on global function resolution.
    (function bindStepperButtons() {
        var plus = document.getElementById('pallets_plus');
        var minus = document.getElementById('pallets_minus');
        if (plus) { plus.addEventListener('click', function() { stepPallets(1); }); }
        if (minus) { minus.addEventListener('click', function() { stepPallets(-1); }); }
    })();

    // ════════════════════════════════════════════════════════════
    // Fetch eligible dates from backend
    // ════════════════════════════════════════════════════════════
    function fetchEligibleDates() {
        var puLat = parseFloat(document.querySelector('input[name="pickup_lat"]')?.value || 0);
        var puLng = parseFloat(document.querySelector('input[name="pickup_lng"]')?.value || 0);
        var deLat = parseFloat(document.querySelector('input[name="delivery_lat"]')?.value || 0);
        var deLng = parseFloat(document.querySelector('input[name="delivery_lng"]')?.value || 0);

        if (!puLat || !deLat) {
            cardsDiv.innerHTML = '<div class="col-12 text-muted py-2">Select pickup and delivery locations to see available dates.</div>';
            return;
        }
        cardsDiv.innerHTML = '<div class="col-12 text-muted py-2"><div class="spinner-border spinner-border-sm me-2" role="status"/>Loading…</div>';

        var tempMode = document.getElementById('portal_temperature_mode');
        var equip = (tempMode && tempMode.value === 'reefer') ? 'reefer' : 'dry';
        var params = 'pickup_lat=' + puLat + '&pickup_lng=' + puLng +
            '&delivery_lat=' + deLat + '&delivery_lng=' + deLng +
            '&pallets=' + (parseInt(palletsEl?.value) || 1) +
            '&weight_lbs=' + (parseFloat(weightEl?.value) || 500) +
            '&equipment=' + equip;

        fetch('/my/booking/eligible-dates?' + params, {credentials: 'same-origin'})
            .then(function(r) { return r.json(); })
            .then(function(data) {
                allDates = data.dates || [];
                dateMap = {};
                allDates.forEach(function(d) { dateMap[d.date] = d; });
                // Auto-select earliest if nothing selected or selected date no longer valid
                if (allDates.length > 0 && (!hiddenDate.value || !dateMap[hiddenDate.value])) {
                    hiddenDate.value = allDates[0].date;
                }
                renderCards();
                if (calExpanded.style.display !== 'none') renderCalendarGrid();
                refreshPalletCapacity();
            })
            .catch(function() {
                cardsDiv.innerHTML = '<div class="col-12 text-danger py-2">Could not load availability. Please try again.</div>';
            });
    }

    // ════════════════════════════════════════════════════════════
    // Render date cards (primary UI)
    // ════════════════════════════════════════════════════════════
    function renderCards() {
        if (allDates.length === 0) {
            cardsDiv.innerHTML = '<div class="col-12 text-muted py-2">No eligible pickup dates found for this movement.</div>';
            viewMore.style.display = 'none';
            displayEl.textContent = '';
            return;
        }

        var sel = hiddenDate.value;
        if (sel && dateMap[sel]) {
            displayEl.textContent = fmtDisplay(sel);
        }

        // Show first 4 dates as cards
        var show = allDates.slice(0, 4);
        var html = '';
        show.forEach(function(d) {
            var cd = fmtCardDate(d.date);
            var isSel = (d.date === sel);
            var onward = d.onward_corridor ? '<small class="d-block" style="font-size:10px;opacity:.8">Onward ' + DAYS_SHORT[new Date(d.estimated_delivery + 'T00:00:00').getDay()] + '</small>' : '';

            if (isSel) {
                html += '<div class="col-6 col-md-3">' +
                    '<button type="button" class="card w-100 border-0 text-white p-2 date-card-selected" style="background:#C62828;cursor:pointer" data-date="' + d.date + '">' +
                    '<small style="font-size:10px;opacity:.9">✓ SELECTED</small>' +
                    '<div style="font-size:14px;font-weight:800;line-height:1.2">' + cd.day + '</div>' +
                    '<div style="font-size:16px;font-weight:700;line-height:1.2">' + cd.date + '</div>' +
                    '<small style="font-size:11px;opacity:.9">Regular Pickup</small>' + onward +
                    '</button></div>';
            } else {
                html += '<div class="col-6 col-md-3">' +
                    '<button type="button" class="card w-100 border p-2 date-card" style="cursor:pointer;transition:border-color .15s" data-date="' + d.date + '">' +
                    '<div style="font-size:14px;font-weight:800;color:#555;line-height:1.2">' + cd.day + '</div>' +
                    '<div style="font-size:16px;font-weight:700;line-height:1.2">' + cd.date + '</div>' +
                    '<small style="font-size:11px;color:#888">Regular Pickup</small>' + onward +
                    '</button></div>';
            }
        });
        cardsDiv.innerHTML = html;
        viewMore.style.display = allDates.length > 4 ? '' : 'none';

        // Bind card clicks
        cardsDiv.querySelectorAll('button[data-date]').forEach(function(btn) {
            btn.addEventListener('click', function() {
                selectDate(btn.getAttribute('data-date'));
            });
        });
    }

    // ════════════════════════════════════════════════════════════
    // Expanded calendar grid (secondary)
    // ════════════════════════════════════════════════════════════
    function renderCalendarGrid() {
        if (!calBody || allDates.length === 0) return;

        // Determine month to show
        var refDate;
        if (hiddenDate.value && dateMap[hiddenDate.value]) {
            refDate = new Date(hiddenDate.value + 'T00:00:00');
        } else {
            refDate = new Date(allDates[0].date + 'T00:00:00');
        }
        calendarMonth = {year: refDate.getFullYear(), month: refDate.getMonth()};

        function drawMonth() {
            var y = calendarMonth.year, m = calendarMonth.month;
            var first = new Date(y, m, 1);
            var last = new Date(y, m + 1, 0);
            var startDay = first.getDay(); // 0=Sun
            var totalDays = last.getDate();
            var today = new Date(); today.setHours(0,0,0,0);
            // Normalized YYYY-MM-DD comparison — never let a
            // datetime value or timezone drift break the highlight.
            var sel = String(hiddenDate.value || '').slice(0, 10);

            var h = '';
            // Header with nav arrows
            h += '<div class="d-flex justify-content-between align-items-center mb-2 px-1">';
            h += '<button type="button" class="btn btn-sm btn-outline-secondary cal-nav-prev" ' + (m === new Date().getMonth() && y === new Date().getFullYear() ? 'disabled' : '') + '>‹</button>';
            h += '<strong style="font-size:15px">' + MONTHS[m] + ' ' + y + '</strong>';
            h += '<button type="button" class="btn btn-sm btn-outline-secondary cal-nav-next">›</button>';
            h += '</div>';

            // Day headers
            h += '<div class="row row-cols-7 g-0 text-center mb-1" style="font-size:11px;color:#999;font-weight:600">';
            ['SUN','MON','TUE','WED','THU','FRI','SAT'].forEach(function(dh) { h += '<div class="col">' + dh + '</div>'; });
            h += '</div>';

            // Weeks
            var day = 1;
            for (var w = 0; w < 6 && day <= totalDays; w++) {
                h += '<div class="row row-cols-7 g-0">';
                for (var d = 0; d < 7; d++) {
                    if ((w === 0 && d < startDay) || day > totalDays) {
                        h += '<div class="col" style="min-height:40px"/>';
                    } else {
                        var ds = y + '-' + String(m+1).padStart(2,'0') + '-' + String(day).padStart(2,'0');
                        var cellDate = new Date(y, m, day);
                        var isPast = cellDate < today;
                        var isEligible = !!dateMap[ds];
                        var isSelected = (ds === sel);
                        var cellStyle = '';
                        var cellCls = '';
                        var dot = '';
                        var disabled = '';

                        if (isSelected) {
                            cellStyle = 'background:#C62828;color:#fff;border-radius:50%;width:36px;height:36px;line-height:36px;margin:0 auto;font-weight:700';
                        } else if (isEligible) {
                            cellStyle = 'font-weight:700;color:#111';
                            dot = '<span style="display:block;width:5px;height:5px;border-radius:50%;background:#C62828;margin:1px auto 0"/>';
                        } else if (isPast) {
                            cellStyle = 'color:#ccc';
                            disabled = 'disabled tabindex="-1"';
                        } else {
                            cellStyle = 'color:#bbb';
                            disabled = 'disabled tabindex="-1"';
                        }

                        h += '<div class="col d-flex flex-column align-items-center justify-content-center" style="min-height:40px">';
                        h += '<button type="button" class="border-0 bg-transparent p-0 text-center cal-cell' + (isEligible ? ' cal-eligible' : '') + '"' +
                            ' style="font-size:13px;' + cellStyle + '"' +
                            ' data-date="' + ds + '" ' + disabled + '>' + day + dot + '</button>';
                        h += '</div>';
                        day++;
                    }
                }
                h += '</div>';
            }
            calBody.innerHTML = h;
            legendDiv.style.display = '';

            // Bind cell clicks
            calBody.querySelectorAll('button.cal-eligible').forEach(function(btn) {
                btn.addEventListener('click', function() {
                    selectDate(btn.getAttribute('data-date'));
                });
            });

            // Bind nav
            calBody.querySelector('.cal-nav-prev')?.addEventListener('click', function(e) { e.preventDefault(); calendarMonth.month--; if (calendarMonth.month < 0) { calendarMonth.year--; calendarMonth.month = 11; } drawMonth(); });
            calBody.querySelector('.cal-nav-next')?.addEventListener('click', function(e) { e.preventDefault(); calendarMonth.month++; if (calendarMonth.month > 11) { calendarMonth.year++; calendarMonth.month = 0; } drawMonth(); });
        }
        drawMonth();
    }

    // ════════════════════════════════════════════════════════════
    // View More toggle
    // ════════════════════════════════════════════════════════════
    if (viewMore) {
        viewMore.addEventListener('click', function(e) {
            e.preventDefault();
            if (calExpanded.style.display === 'none') {
                calExpanded.style.display = '';
                viewMore.textContent = 'Hide Calendar ▴';
                renderCalendarGrid();
            } else {
                calExpanded.style.display = 'none';
                viewMore.textContent = 'View More Pickup Dates ▾';
            }
        });
    }

    // ════════════════════════════════════════════════════════════
    // Per-Pallet Allocation Engine
    // ════════════════════════════════════════════════════════════
    var deliveryStopCount = document.querySelectorAll('.delivery-stop-breakdown-row').length;
    var palletAllocBody = document.getElementById('pallet_allocation_body');
    var palletAllocSummary = document.getElementById('pallet_allocation_summary');
    var allocsJsonField = document.getElementById('pallet_allocations_json');

    function buildPalletAllocations() {
        if (!palletAllocBody || deliveryStopCount <= 1) return;
        var physInput = document.getElementById('pallets_input');
        var physical = parseInt(physInput ? physInput.value : '1') || 1;
        var html = '';
        for (var p = 1; p <= physical; p++) {
            html += '<div class="d-flex align-items-center py-2 border-bottom pallet-alloc-row" data-pallet="' + p + '">';
            html += '<strong class="me-3" style="min-width:80px">PALLET ' + p + '</strong>';
            html += '<div class="flex-grow-1"><small class="text-muted">Deliver To:</small><br/>';
            for (var s = 1; s <= deliveryStopCount; s++) {
                var stopEl = document.querySelector('.delivery-stop-breakdown-row:nth-child(' + s + ') .flex-grow-1');
                var stopName = stopEl ? stopEl.textContent.trim().split('\\n')[0] : ('Stop ' + s);
                html += '<label class="me-2" style="cursor:pointer;white-space:nowrap">';
                html += '<input type="checkbox" class="pallet-stop-check" data-pallet="' + p + '" data-stop="' + s + '" onchange="updateAllocations()"/> ';
                html += stopName.substring(0, 20) + (stopName.length > 20 ? '…' : '');
                html += '</label>';
            }
            html += '</div>';
            html += '<span class="badge rounded-pill ms-2 pallet-status-badge" data-pallet="' + p + '" style="min-width:90px;background:#6c757d;color:#fff">DEDICATED</span>';
            html += '</div>';
        }
        palletAllocBody.innerHTML = html;
        var placeholder = document.getElementById('pallet_alloc_placeholder');
        if (placeholder) placeholder.style.display = 'none';
        updateAllocations();
    }

    window.updateAllocations = function() {
        if (deliveryStopCount <= 1) return;
        var physInput = document.getElementById('pallets_input');
        var physical = parseInt(physInput ? physInput.value : '1') || 1;
        var allocs = [];
        for (var p = 1; p <= physical; p++) {
            var stops = [];
            document.querySelectorAll('.pallet-stop-check[data-pallet="' + p + '"]').forEach(function(cb) {
                if (cb.checked) stops.push(parseInt(cb.dataset.stop));
            });
            allocs.push({pallet: p, stops: stops, shared: stops.length > 1});
        }
        allocs.forEach(function(a) {
            var badge = document.querySelector('.pallet-status-badge[data-pallet="' + a.pallet + '"]');
            if (badge) {
                if (a.shared) { badge.textContent = 'SHARED — ' + a.stops.length + ' STOPS'; badge.style.background = '#7b1fa2'; badge.style.color = '#fff'; }
                else { badge.textContent = 'DEDICATED'; badge.style.background = '#6c757d'; badge.style.color = '#fff'; }
            }
        });
        for (var s = 1; s <= deliveryStopCount; s++) {
            var stopPallets = [];
            allocs.forEach(function(a) { if (a.stops.indexOf(s) >= 0) stopPallets.push(a.pallet); });
            var countBadge = document.getElementById('stop_pallet_badge_' + s);
            if (countBadge) countBadge.textContent = 'Pallets: ' + (stopPallets.length > 0 ? stopPallets.join(', ') : '—');
            var sharedBadge = document.getElementById('stop_shared_badge_' + s);
            if (sharedBadge) { sharedBadge.style.display = allocs.some(function(a) { return a.shared && a.stops.indexOf(s) >= 0; }) ? '' : 'none'; }
        }
        if (allocsJsonField) allocsJsonField.value = JSON.stringify(allocs);
        var legacyEl = document.getElementById('legacy_pallets');
        if (legacyEl) legacyEl.value = physical;
        var modeInput = document.getElementById('shared_pallet_mode_input');
        if (modeInput) modeInput.value = allocs.some(function(a) { return a.shared; }) ? '1' : '0';
        if (palletAllocSummary) {
            var sc = allocs.filter(function(a) { return a.shared; }).length;
            var dc = allocs.filter(function(a) { return !a.shared; }).length;
            var parts = [physical + ' physical pallet' + (physical !== 1 ? 's' : '')];
            if (sc > 0) parts.push(sc + ' shared'); if (dc > 0) parts.push(dc + ' dedicated');
            palletAllocSummary.textContent = parts.join(' · ');
        }
        for (var s = 1; s <= deliveryStopCount; s++) {
            var sp = []; allocs.forEach(function(a) { if (a.stops.indexOf(s) >= 0) sp.push(a.pallet); });
            var hiddenInput = document.querySelector('input[name="delivery_pallets_' + s + '"]');
            if (hiddenInput) hiddenInput.value = sp.length || 1;
        }
    };

    var physPalletInput = document.getElementById('pallets_input');
    if (physPalletInput) {
        physPalletInput.addEventListener('input', function() { buildPalletAllocations(); autoWeight(); fetchEligibleDates(); });
    }
    if (deliveryStopCount > 1) buildPalletAllocations();

    // Initialize Reefer UI on page load (not just on change)
    togglePortalTemperature();
    // Fetch on load
    fetchEligibleDates();
    var tempSelect = document.getElementById('portal_temperature_mode');
    if (tempSelect) tempSelect.addEventListener('change', fetchEligibleDates);

    // ════════════════════════════════════════════════════════════
    // Appointment Required Window
    // ════════════════════════════════════════════════════════════
    window.toggleAppointmentWindow = function() {
        var cb = document.getElementById('appointment_checkbox');
        var panel = document.getElementById('appointment_window');
        var timingType = document.querySelector('input[name="delivery_timing_type_1"]');
        if (cb && panel) {
            if (cb.checked) {
                panel.style.display = '';
                if (timingType) timingType.value = 'time_window';
                updateAppointmentInfo();
            } else {
                panel.style.display = 'none';
                if (timingType) timingType.value = 'flexible';
            }
        }
    };
    function updateAppointmentInfo() {
        var dateEl = document.getElementById('appt_delivery_date');
        var tzEl = document.getElementById('appt_timezone');
        var hoursEl = document.getElementById('appt_receiving_hours');
        // Use delivery location timezone from hidden field
        var tzField = document.querySelector('input[name="delivery_tz_1"]');
        var tz = tzField ? tzField.value : 'America/Toronto';
        // Friendly timezone label
        var tzMap = {'America/Toronto':'Eastern Time (ET)','America/Vancouver':'Pacific Time (PT)','America/Edmonton':'Mountain Time (MT)','America/Winnipeg':'Central Time (CT)','America/Chicago':'Central Time (CT)','America/New_York':'Eastern Time (ET)','America/Halifax':'Atlantic Time (AT)','America/St_Johns':'Newfoundland Time (NT)'};
        var tzFriendly = tzMap[tz] || tz;
        if (tzEl) tzEl.textContent = tzFriendly;
        if (hoursEl) hoursEl.textContent = 'Check with receiver'; // default if not configured
        // Estimate delivery date: pickup date + 1 day
        var hiddenDate = document.getElementById('requested_pickup_date');
        if (hiddenDate && hiddenDate.value) {
            var pd = new Date(hiddenDate.value + 'T00:00:00');
            pd.setDate(pd.getDate() + 1);
            var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
            var months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
            if (dateEl) dateEl.textContent = days[pd.getDay()] + ', ' + months[pd.getMonth()] + ' ' + pd.getDate() + ', ' + pd.getFullYear();
        }
        updateTimeline();
    }
    function updateTimeline() {
        var from = document.getElementById('appt_from');
        var to = document.getElementById('appt_to');
        var fill = document.getElementById('appt_timeline_fill');
        var msg = document.getElementById('appt_validation_msg');
        if (!from || !to || !fill) return;
        var fv = from.value, tv = to.value;
        if (fv && tv) {
            var fmin = parseInt(fv.split(':')[0])*60 + parseInt(fv.split(':')[1]);
            var tmin = parseInt(tv.split(':')[0])*60 + parseInt(tv.split(':')[1]);
            if (fmin >= tmin) {
                if (msg) { msg.style.display = ''; msg.textContent = 'End time must be later than start time.'; }
                fill.style.width = '0';
            } else {
                if (msg) msg.style.display = 'none';
                var pctLeft = (fmin / 1440) * 100;
                var pctWidth = ((tmin - fmin) / 1440) * 100;
                fill.style.left = pctLeft + '%';
                fill.style.width = pctWidth + '%';
            }
        }
    }
    // Hook From/To inputs to update timeline
    var af = document.getElementById('appt_from'), at = document.getElementById('appt_to');
    if (af) af.addEventListener('input', updateTimeline);
    if (at) at.addEventListener('input', updateTimeline);
    // Hook pickup date change to update appointment date
    var pickupDateInput = document.getElementById('requested_pickup_date');
    if (pickupDateInput) {
        var origSelectDate = window.selectDate;
        if (typeof origSelectDate === 'function') {
            window.selectDate = function(ds) {
                origSelectDate(ds);
                if (document.getElementById('appointment_checkbox') && document.getElementById('appointment_checkbox').checked) {
                    updateAppointmentInfo();
                }
            };
        }
    }
});

document.addEventListener('DOMContentLoaded', function() {
    var SAVED_LOCS = [];
    try {
        var locsEl = document.getElementById('saved_locations_data');
        SAVED_LOCS = locsEl ? JSON.parse(locsEl.textContent || '[]') : [];
    } catch (e) { SAVED_LOCS = []; }

    var extraPickupCount = 0;
    var extraDeliveryCount = 0;

    function fmtHours(h) {
        if (!h) return 'Closed';
        var f = function(x) {
            var hh = Math.floor(x), mm = Math.round((x - hh) * 60);
            if (mm === 60) { hh += 1; mm = 0; }
            var ap = 'AM', hh12 = hh;
            if (hh >= 12) ap = 'PM';
            if (hh12 > 12) hh12 -= 12;
            if (hh12 === 0) hh12 = 12;
            return hh12 + ':' + (mm < 10 ? '0' : '') + mm + ' ' + ap;
        };
        return f(h[0]) + ' – ' + f(h[1]);
    }

    function hoursForDay(loc, dayIndex) {
        var locRec = null;
        for (var i = 0; i < SAVED_LOCS.length; i++) {
            if (SAVED_LOCS[i].id === loc) { locRec = SAVED_LOCS[i]; break; }
        }
        if (!locRec || !locRec.hours) return null;
        return locRec.hours[String(dayIndex)] || null;
    }

    function locOptions(selectedId, type) {
        var html = '<option value="">— Select saved location —</option>';
        SAVED_LOCS.forEach(function(l) {
            if (type && l.location_type !== type && l.location_type !== 'both') return;
            html += '<option value="' + l.id + '"' + (String(l.id) === String(selectedId) ? ' selected' : '') + '>'
                + (l.business_name || l.name) + ' (' + l.city + ')</option>';
        });
        return html;
    }

    function stopCardHtml(key, type, index) {
        var idp = key.replace(/[^a-zA-Z0-9]/g, '_');
        return '<div class="card mt-2 extra-stop-card" data-stop-key="' + key + '" data-stop-type="' + type + '">'
            + '<div class="card-body py-2">'
            + '<div class="d-flex justify-content-between align-items-center">'
            + '<strong>' + (type === 'pickup' ? 'PICKUP ' : 'DELIVERY ') + index + '</strong>'
            + '<button type="button" class="btn-close" onclick="removeStopCard(\'' + key + '\')" aria-label="Remove"></button>'
            + '</div>'
            + '<div class="row g-2 mt-1">'
            + '<div class="col-md-5"><small class="text-muted">Saved Location</small>'
            + '<select class="form-select form-select-sm stop-saved-location" id="' + idp + '_loc">' + locOptions('', type) + '</select></div>'
            + '<div class="col-md-7"><small class="text-muted">Facility Hours (today)</small><br/><span class="stop-hours-display small">—</span></div>'
            + '<div class="col-md-3"><label class="form-check form-check-inline"><input type="checkbox" class="form-check-input stop-liftgate"/> Liftgate</label></div>'
            + '<div class="col-md-3"><label class="form-check form-check-inline"><input type="checkbox" class="form-check-input stop-appointment"/> Appointment</label></div>'
            + '<div class="col-md-3"><select class="form-select form-select-sm stop-timing">'
            + '<option value="flexible">Flexible</option>'
            + '<option value="time_window">Time Window</option>'
            + '<option value="exact_appointment">Exact</option>'
            + '<option value="deadline">Deadline</option></select></div>'
            + '<div class="col-md-3"><input type="number" class="form-control form-control-sm stop-service-minutes" value="15" min="0" step="5"/> min svc</div>'
            + '<div class="col-md-6 stop-window-fields" style="display:none">'
            + '<input type="time" class="form-control form-control-sm d-inline-block stop-window-start" style="width:45%"/> — '
            + '<input type="time" class="form-control form-control-sm d-inline-block stop-window-end" style="width:45%"/></div>'
            + '<div class="col-md-12"><input type="text" class="form-control form-control-sm stop-instructions" placeholder="Stop instructions (dock, door, contact…)"/></div>'
            + '</div></div></div>';
    }

    window.addExtraPickupCard = function() {
        extraPickupCount += 1;
        var key = 'stp-pu-' + extraPickupCount;
        var el = document.createElement('div');
        el.innerHTML = stopCardHtml(key, 'pickup', extraPickupCount + 1);
        document.getElementById('extra_pickup_cards').appendChild(el.firstChild);
        bindStopCard(key);
        refreshRouteChain();
        buildMovementGrid();
    };
    window.addExtraDeliveryCard = function() {
        extraDeliveryCount += 1;
        var key = 'stp-de-x' + extraDeliveryCount;
        var el = document.createElement('div');
        el.innerHTML = stopCardHtml(key, 'delivery', extraDeliveryCount + 1);
        document.getElementById('extra_delivery_cards').appendChild(el.firstChild);
        bindStopCard(key);
        refreshRouteChain();
        buildMovementGrid();
    };

    function bindStopCard(key) {
        var card = document.querySelector('.extra-stop-card[data-stop-key="' + key + '"]');
        if (!card) return;
        var sel = card.querySelector('.stop-saved-location');
        var hoursDisp = card.querySelector('.stop-hours-display');
        var timing = card.querySelector('.stop-timing');
        var winFields = card.querySelector('.stop-window-fields');
        var update = function() {
            var locId = parseInt(sel.value);
            var today = new Date().getDay();
            var mapped = (today + 6) % 7; // JS Sun=0 → Odoo Mon=0
            var h = hoursForDay(locId, mapped);
            hoursDisp.textContent = fmtHours(h);
            hoursDisp.style.color = h ? '#198754' : '#dc3545';
        };
        sel.addEventListener('change', update);
        timing.addEventListener('change', function() {
            winFields.style.display = timing.value === 'flexible' ? 'none' : '';
        });
        update();
    }

    window.removeStopCard = function(key) {
        var card = document.querySelector('.extra-stop-card[data-stop-key="' + key + '"]');
        if (card) card.remove();
        refreshRouteChain();
        buildMovementGrid();
    };

    function pickupStops() {
        // Pickup 1 = the legacy form fields; extras = cards.
        var stops = [{key: 'stp-pu-1', type: 'pickup', legacy: true}];
        document.querySelectorAll('#extra_pickup_cards .extra-stop-card').forEach(function(c) {
            stops.push({key: c.dataset.stopKey, type: 'pickup', legacy: false, card: c});
        });
        return stops;
    }
    function deliveryStops() {
        var stops = [];
        var rows = document.querySelectorAll('.delivery-stop-breakdown-row');
        rows.forEach(function(row, idx) {
            stops.push({key: 'stp-de-' + (idx + 1), type: 'delivery', legacy: true, index: idx + 1});
        });
        // Single-step-1 delivery (no visible row)
        var single = document.querySelector('input[name="delivery_loc_id_1"]');
        if (!rows.length && single) {
            stops.push({key: 'stp-de-1', type: 'delivery', legacy: true, index: 1});
        }
        document.querySelectorAll('#extra_delivery_cards .extra-stop-card').forEach(function(c) {
            stops.push({key: c.dataset.stopKey, type: 'delivery', legacy: false, card: c});
        });
        return stops;
    }

    function refreshRouteChain() {
        var chain = '';
        deliveryStops().forEach(function(d) { chain += ' → Delivery '; });
        document.getElementById('route_stops_chain').textContent = '';
        var parts = [];
        pickupStops().forEach(function(p, i) { parts.push('Pickup ' + (i + 1)); });
        deliveryStops().forEach(function(d, i) { parts.push('Delivery ' + (i + 1)); });
        document.getElementById('route_stops_chain').textContent = ' → ' + parts.join(' → ');
    }

    function builderActive() {
        if (extraPickupCount > 0) return true;
        // Shared pallet (multi-delivery) also generalizes the booking.
        var shared = false;
        document.querySelectorAll('.movement-delivery-check:checked').forEach(function(cb) {
            var key = cb.dataset.palletKey;
            var count = document.querySelectorAll('.movement-delivery-check:checked[data-pallet-key="' + key + '"]').length;
            if (count > 1) shared = true;
        });
        return shared;
    }

    function buildMovementGrid() {
        var gridCard = document.getElementById('movement_grid_card');
        var body = document.getElementById('movement_grid_body');
        var physInput = document.getElementById('pallets_input');
        var physical = parseInt(physInput ? physInput.value : '1') || 1;
        var show = pickupStops().length > 1 || deliveryStops().length > 1 || extraPickupCount > 0;
        if (!body) return;
        if (!show) { if (gridCard) gridCard.style.display = 'none'; return; }
        if (gridCard) gridCard.style.display = '';
        var html = '';
        for (var p = 1; p <= physical; p++) {
            html += '<div class="d-flex align-items-center py-2 border-bottom movement-row" data-pallet="' + p + '">';
            html += '<strong class="me-2" style="min-width:75px">PALLET ' + p + '</strong>';
            html += '<div class="me-3"><small class="text-muted">Pickup From</small><br/>';
            html += '<select class="form-select form-select-sm movement-pickup" data-pallet="' + p + '">';
            pickupStops().forEach(function(s, i) {
                html += '<option value="' + s.key + '"' + (i === 0 ? ' selected' : '') + '>Pickup ' + (i + 1) + '</option>';
            });
            html += '</select></div>';
            html += '<div class="flex-grow-1"><small class="text-muted">Deliver To</small><br/>';
            deliveryStops().forEach(function(s, i) {
                html += '<label class="me-2" style="cursor:pointer;white-space:nowrap">';
                html += '<input type="checkbox" class="movement-delivery-check" data-pallet-key="pal-' + p + '" data-stop-key="' + s.key + '" data-delivery-index="' + (i + 1) + '" onchange="buildMovementGrid()"/> ';
                html += 'Delivery ' + (i + 1);
                html += '</label>';
            });
            html += '</div></div>';
        }
        body.innerHTML = html;
    }

    function legacyDeliveryLocId(idx) {
        var el = document.querySelector('input[name="delivery_loc_id_' + idx + '"]');
        return el ? parseInt(el.value) || null : null;
    }
    function stopPayload(s) {
        if (s.legacy) {
            if (s.type === 'pickup') {
                var puLoc = document.querySelector('input[name="pickup_loc_id"]');
                return {
                    stop_key: s.key, stop_type: 'pickup',
                    saved_location_id: puLoc ? (parseInt(puLoc.value) || null) : null,
                    liftgate_required: !!(document.querySelector('input[name="liftgate_pickup"]') || {}).checked,
                    appointment_required: !!(document.querySelector('input[name="appointment"]') || {}).checked,
                    timing_type: 'flexible', service_time_minutes: 15, instructions: ''
                };
            }
            var idx = s.index;
            var timingEl = document.querySelector('select[name="delivery_timing_type_' + idx + '"]');
            var wStart = document.querySelector('input[name="delivery_window_start_' + idx + '"]');
            var wEnd = document.querySelector('input[name="delivery_window_end_' + idx + '"]');
            return {
                stop_key: s.key, stop_type: 'delivery',
                saved_location_id: legacyDeliveryLocId(idx),
                liftgate_required: !!(document.querySelector('input[name="liftgate_delivery"]') || {}).checked,
                appointment_required: !!(document.querySelector('input[name="appointment"]') || {}).checked,
                timing_type: timingEl ? timingEl.value : 'flexible',
                window_start: wStart ? wStart.value : '',
                window_end: wEnd ? wEnd.value : '',
                service_time_minutes: 15, instructions: ''
            };
        }
        var c = s.card;
        var sel = c.querySelector('.stop-saved-location');
        var timing = c.querySelector('.stop-timing');
        return {
            stop_key: s.key, stop_type: s.type,
            saved_location_id: parseInt(sel.value) || null,
            liftgate_required: c.querySelector('.stop-liftgate').checked,
            appointment_required: c.querySelector('.stop-appointment').checked,
            timing_type: timing.value,
            window_start: c.querySelector('.stop-window-start').value,
            window_end: c.querySelector('.stop-window-end').value,
            service_time_minutes: parseInt(c.querySelector('.stop-service-minutes').value) || 15,
            instructions: c.querySelector('.stop-instructions').value
        };
    }

    var form = document.querySelector('form[action="/my/booking/quote"]');
    if (form) {
        form.addEventListener('submit', function(ev) {
            if (!builderActive()) {
                document.getElementById('route_stops_json').value = '';
                document.getElementById('pallet_movements_json').value = '';
                return;
            }
            var stops = pickupStops().concat(deliveryStops());
            var routeStops = stops.map(stopPayload);
            var movements = [];
            var physical = parseInt((document.getElementById('pallets_input') || {}).value) || 1;
            var legacyAllocs = [];
            for (var p = 1; p <= physical; p++) {
                var puSelect = document.querySelector('.movement-pickup[data-pallet="' + p + '"]');
                var pickupKey = puSelect ? puSelect.value : 'stp-pu-1';
                var deliveryKeys = [];
                var deliveryIdx = [];
                document.querySelectorAll('.movement-delivery-check:checked[data-pallet-key="pal-' + p + '"]').forEach(function(cb) {
                    deliveryKeys.push(cb.dataset.stopKey);
                    deliveryIdx.push(parseInt(cb.dataset.deliveryIndex));
                });
                movements.push({
                    key: 'pal-' + p, label: 'Pallet-' + p,
                    weight_lbs: 500, shared: deliveryKeys.length > 1,
                    pickup_stop_key: pickupKey, delivery_stop_keys: deliveryKeys
                });
                legacyAllocs.push({pallet: p, stops: deliveryIdx, shared: deliveryKeys.length > 1});
            }
            document.getElementById('route_stops_json').value = JSON.stringify(routeStops);
            document.getElementById('pallet_movements_json').value = JSON.stringify(movements);
            document.getElementById('pallet_allocations_json').value = JSON.stringify(legacyAllocs);
        });
    }

    refreshRouteChain();
});

div.script:
document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('.contact-toggle').forEach(function(link) {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            var targetId = this.getAttribute('data-target');
            var panel = document.getElementById(targetId);
            if (panel) {
                var isOpen = panel.style.display !== 'none';
                panel.style.display = isOpen ? 'none' : '';
                this.textContent = (isOpen ? 'CONTACT & INSTRUCTIONS ▾' : 'CONTACT & INSTRUCTIONS ▴');
            }
        });
    });
});
